import { useState, useEffect, useRef, useCallback } from 'react';

export default function useVoice() {
  const [speaking, setSpeaking] = useState(false);
  const [supported, setSupported] = useState(false);
  const utterRef = useRef(null);

  useEffect(() => {
    setSupported('speechSynthesis' in window);
    return () => { window.speechSynthesis?.cancel(); };
  }, []);

  const speak = useCallback((text) => {
    if (!supported) return;
    window.speechSynthesis.cancel();
    const utter = new SpeechSynthesisUtterance(text);
    // Pick best available English voice
    const voices = window.speechSynthesis.getVoices();
    const preferred = voices.find(v =>
      v.name.includes('Google') || v.name.includes('Natural') || v.name.includes('Neural')
    ) || voices.find(v => v.lang.startsWith('en')) || voices[0];
    if (preferred) utter.voice = preferred;
    utter.rate = 0.92;
    utter.pitch = 1;
    utter.volume = 1;
    utter.onstart = () => setSpeaking(true);
    utter.onend = () => setSpeaking(false);
    utter.onerror = () => setSpeaking(false);
    utterRef.current = utter;
    window.speechSynthesis.speak(utter);
  }, [supported]);

  const stop = useCallback(() => {
    window.speechSynthesis?.cancel();
    setSpeaking(false);
  }, []);

  // Build a full readable script for a tool
  const speakTool = useCallback((tool) => {
    const lines = [
      `${tool.n}.`,
      tool.d,
      tool.about ? `About: ${tool.about}` : '',
      tool.steps?.length ? `How to get started: ${tool.steps.join('. ')}` : '',
      tool.tips?.length ? `Pro tips: ${tool.tips.join('. ')}` : '',
    ].filter(Boolean).join('  ');
    speak(lines);
  }, [speak]);

  // Speak only the quick summary (description + first 2 steps)
  const speakQuick = useCallback((tool) => {
    const lines = [
      `${tool.n}.`,
      tool.d,
      tool.steps?.length ? `Quick start: ${tool.steps.slice(0, 2).join('. ')}` : '',
    ].filter(Boolean).join('  ');
    speak(lines);
  }, [speak]);

  return { speaking, supported, speakTool, speakQuick, stop, speak };
}
